// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { openOwnerDetail, openAddPetForm } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));

    await page.goto(baseUrl);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
    await openOwnerDetail(page);

    await expect(page).toHaveURL(`${baseUrl}/petclinic/owners/1`);
    await expect(page.getByRole("button", { name: "Add New Pet" })).toHaveText("Add New Pet");

    await openAddPetForm(page);

    await expect(page).toHaveURL(`${baseUrl}/petclinic/owners/1/pets/add`);
    await expect(page.getByRole("heading", { name: "Add Pet" })).toHaveText("Add Pet");
    await expect(page.getByRole("button", { name: "Save Pet" })).toBeDisabled();

    expect(pageErrors, 'uncaught page errors').toEqual([]);
});
